      "acerca": {
        "titulo": "วิธีอ่านกราฟิก",
        "p1": "แต่ละกราฟิกแสดง <strong>เฉพาะคอร์ดที่แผนที่นั้นใช้</strong> เท่านั้น และ\n        ด้วยรูปแบบที่แผนที่นั้นกำหนดเอง ไม่ว่าจะเป็นดาวที่มีโทนิกอยู่\n        ตรงกลาง ตารางกริด กรวยที่บรรจบเข้าหากัน หรือน้ำตกที่ไหลลง\n        แบบซิกแซก ถ้าคอร์ดหนึ่งไม่อยู่ในภาพ นั่นเป็นเพราะมันไม่ได้อยู่\n        ในแผนที่นั้น — และด้วยเหตุนี้ระบบจึงไม่เสนอให้คุณเป็นทางออกด้วย",
        "p2": "<strong>เอาเมาส์ไปวางบนคอร์ด</strong> แล้วส่วนอื่นจะเบลอลง:\n        จะสว่างอยู่แค่จุดที่คุณไปได้จากตรงนั้น ภายในกราฟิกเดียวกันนี้\n        รายการทางด้านขวาจะแยกสิ่งที่แผนที่เสนอ (พร้อมคำอธิบายของมันเอง)\n        ออกจากความสัมพันธ์อื่นๆ ที่มีอยู่ระหว่างคอร์ดเหล่านั้น และจะระบุ\n        ดีกรีของแต่ละคอร์ด — ii, V7, bVI — ซึ่งเป็นสิ่งที่บอกตำแหน่งจริงๆ",
        "p3": "<strong>คลิก</strong> เพื่อล็อกคอร์ดไว้และดูวิธีเล่น:\n        การจับคอร์ดบนกีตาร์และเบส และคีย์บนเปียโน ตำแหน่ง\n        ต่างๆ คำนวณจากโน้ตของคอร์ด โดยพยายามให้โน้ตราก\n        อยู่ที่เบสและให้มือเอื้อมถึง — ตัวเลขข้าง\n        ในจุดคือดีกรี (1 คือโน้ตราก, 3 คือคอร์ดที่สาม, b7 คือเซเวนไมเนอร์…)",
        "p4": "ด้านบนของกราฟิกคุณสามารถ <strong>เปลี่ยนโทนิก</strong> ได้: แผนที่\n        ทั้งหมดจะถูกทรานสโพสไปยังคีย์นั้น รวมทั้งคอร์ดและโน้ตด้วย เพื่อ\n        ไม่ให้คุณฝึกซ้อมอยู่ใน Do ตลอด และด้วย\n        <strong>วงกลมคู่ห้า</strong> คุณจะเปลี่ยนไปดูมุมมองอ้างอิง\n        ที่แสดงระบบทั้งหมดของ 12 คีย์ พร้อมกับการเดินคอร์ดนี้\n        ที่ถูกไฮไลต์อยู่ด้านบน",
        "p5": "สิ่งนี้ไม่ได้มาแทนที่การเล่นและการฟัง — มันเป็นแค่แผนที่ ไม่ใช่พื้นที่จริง\n        มันมีไว้เพื่อเป็นข้อมูลอ้างอิงทางภาพที่รวดเร็วขณะที่คุณอิมโพรไวส์หรือ\n        แต่งการเดินคอร์ดใหม่"
      },
      "grafoPista": "เอาเมาส์ไปวางบนคอร์ดเพื่อดูว่าคุณไปที่ไหนได้จากจุดนั้น ·\n          คลิกเพื่อล็อกไว้และดูวิธีเล่น",
